def deadline_priority(minutes_remaining: int, has_blocker: bool) -> str:
    if has_blocker:
        return "BLOCKED"
    if minutes_remaining < 0:
        return "OVERDUE"
    if minutes_remaining <= 60:
        return "DUE_SOON"
    if minutes_remaining <= 1440:
        return "TODAY"
    return "SCHEDULED"
